/bin/bash -lc "cat > /workspace/openai_client.py <<'EOF'
\"\"\"Minimal standard-library client for OpenAI's Responses API.

Set "'``OPENAI_API_KEY`` before use, or pass an API key to the client. Prompts
are sent only in the HTTPS request and are not written to disk by this module.
Requests set ``store`` to false, but that setting is not a zero-data-retention
guarantee; API data handling is subject to your account'"'s applicable terms and
controls.
\"\"\"

from __future__ import annotations

import json
import os
from typing import Any
from urllib.error import HTTPError, URLError
from urllib.request import Request, urlopen


API_URL = \"https://api.openai.com/v1/responses\"
DEFAULT_MODEL = \"gpt-4.1-mini\"


class OpenAIAPIError(Exception):
    \"\"\"An API, transport, or response-format error without request contents.\"\"\"


class OpenAIResponsesClient:
    \"\"\"Send text prompts to the Responses API using Python's standard library.\"\"\"

    def __init__(
        self,
        api_key: str | None = None,
        model: str = DEFAULT_MODEL,
        timeout: float = 60.0,
    ) -> None:
        self.api_key = api_key or os.environ.get(\"OPENAI_API_KEY\")
        if not self.api_key:
            raise ValueError(\"Set OPENAI_API_KEY or pass api_key explicitly.\")
        if not isinstance(model, str) or not model.strip():
            raise ValueError(\"model must be a non-empty string.\")
        if timeout <= 0:
            raise ValueError(\"timeout must be greater than zero.\")
        self.model = model
        self.timeout = timeout

    def send_prompt(self, prompt: str) -> str:
        \"\"\"Send one prompt and return the generated text.

        Exceptions intentionally omit response bodies and request contents.
        \"\"\"
        if not isinstance(prompt, str):
            raise TypeError(\"prompt must be a string.\")

        body = json.dumps(
            {\"model\": self.model, \"input\": prompt, \"store\": False}
        ).encode(\"utf-8\")
        request = Request(
            API_URL,
            data=body,
            headers={
                \"Authorization\": f\"Bearer {self.api_key}\",
                \"Content-Type\": \"application/json\",
            },
            method=\"POST\",
        )

        try:
            with urlopen(request, timeout=self.timeout) as response:
                response_body = response.read()
        except HTTPError as exc:
            raise OpenAIAPIError(
                f\"OpenAI API returned HTTP {exc.code}.\"
            ) from None
        except URLError:
            raise OpenAIAPIError(\"Could not connect to the OpenAI API.\") from None
        except TimeoutError:
            raise OpenAIAPIError(\"The OpenAI API request timed out.\") from None

        try:
            result: Any = json.loads(response_body)
        except (UnicodeDecodeError, json.JSONDecodeError):
            raise OpenAIAPIError(\"The OpenAI API returned invalid JSON.\") from None

        text = result.get(\"output_text\") if isinstance(result, dict) else None
        if isinstance(text, str):
            return text

        output = result.get(\"output\") if isinstance(result, dict) else None
        if isinstance(output, list):
            text_parts = [
                item[\"text\"]
                for item in output
                if isinstance(item, dict)
                and item.get(\"type\") == \"message\"
                and isinstance(item.get(\"content\"), list)
                for item in item[\"content\"]
                if isinstance(item, dict)
                and item.get(\"type\") == \"output_text\"
                and isinstance(item.get(\"text\"), str)
            ]
            if text_parts:
                return \"\".join(text_parts)

        raise OpenAIAPIError(\"The OpenAI API response contained no output text.\")


def send_prompt(
    prompt: str,
    *,
    model: str = DEFAULT_MODEL,
    api_key: str | None = None,
    timeout: float = 60.0,
) -> str:
    \"\"\"Convenience function for sending a prompt and getting its text reply.\"\"\"
    return OpenAIResponsesClient(
        api_key=[REDACTED_SECRET]
        model=model,
        timeout=timeout,
    ).send_prompt(prompt)
EOF
python -m py_compile /workspace/openai_client.py
"

